            true -> 1
          end

        {unit, pos2} = take_unit(text, pos + 1, want - 1, <<c>>)
        keep(text, pos2, capacity, acc, used, clamped, unit, value, report)
    end
  end

  # only bytes that ACTUALLY look like continuations are taken: the wire imposes
  # no encoding, so a string may legitimately hold a stray lead byte, and one at
  # the end of a text must not swallow the closing quote
  defp take_unit(_text, pos, 0, unit), do: {unit, pos}

  defp take_unit(text, pos, left, unit) do
    c = at(text, pos)

    if pos < byte_size(text) and (c &&& 0xC0) == 0x80 do
      take_unit(text, pos + 1, left - 1, unit <> <<c>>)
    else
      {unit, pos}
    end
  end

  defp keep(text, pos, capacity, acc, used, clamped, unit, value, report) do
    size = byte_size(unit)

    if capacity >= 0 and used + size > capacity do
      scan_body(text, pos, capacity, acc, used, true, value, report)
    else
      scan_body(text, pos, capacity, [unit | acc], used + size, clamped, value, report)
    end
  end

  defp scan_escape(text, pos, value, report) do
    case at(text, pos) do
      ?" -> {"\"", pos + 1}
      ?\\ -> {"\\", pos + 1}
      ?/ -> {"/", pos + 1}
      ?b -> {<<0x08>>, pos + 1}
      ?f -> {<<0x0C>>, pos + 1}
      ?n -> {"\n", pos + 1}
      ?r -> {"\r", pos + 1}
      ?t -> {"\t", pos + 1}
      ?u -> scan_unicode(text, pos + 1, value, report)
      _ -> bad(value, report)
    end
  end

  defp scan_unicode(text, pos, value, report) do
    high = hex4(text, pos, value, report)
    pos = pos + 4

    {code, pos} =
      if high >= 0xD800 and high <= 0xDBFF and at(text, pos) == ?\\ and at(text, pos + 1) == ?u do
        low = hex4(text, pos + 2, value, report)

        if low >= 0xDC00 and low <= 0xDFFF do
          {0x10000 + ((high - 0xD800) <<< 10) + (low - 0xDC00), pos + 6}
        else
          # a lone lead surrogate never found its partner
          {high, pos}
        end
      else
        {high, pos}
      end

    # a surrogate half with no partner has no UTF-8 encoding: encoding it anyway
    # would manufacture CESU-8 out of input that was valid JSON, so it reads as
    # the replacement character (§16.3)
    code = if code >= 0xD800 and code <= 0xDFFF, do: 0xFFFD, else: code
    {<<code::utf8>>, pos}
  end

  defp hex4(text, pos, value, report) do
    if pos + 4 > byte_size(text), do: bad(value, report)

    Enum.reduce(0..3, 0, fn i, acc ->
      c = :binary.at(text, pos + i)

      digit =
        cond do
          c >= ?0 and c <= ?9 -> c - ?0
          c >= ?a and c <= ?f -> c - ?a + 10
          c >= ?A and c <= ?F -> c - ?A + 10
          true -> bad(value, report)
        end

      (acc <<< 4) + digit
    end)
  end

  # ---- one RFC 8259 number ----
  #
  # Scanning the production is what makes a typo in an authoring file a
  # DIAGNOSTIC rather than a value: "1-2" scans as 1 and leaves "-2" where the
  # object expects a comma, so the text is malformed (§16.2). A permissive scan
  # would hand "1-2" to a digit loop and report a clamp.
  defp walk_number(text, pos) do
    pos = space(text, pos)
    pos = if at(text, pos) == ?-, do: pos + 1, else: pos

    case at(text, pos) do
      ?0 ->
        walk_frac(text, pos + 1, true)

      c when c >= ?1 and c <= ?9 ->
        walk_frac(text, digits(text, pos), true)

      _ ->
        :bad
    end
  end

  defp digits(text, pos) do
    c = at(text, pos)
    if c >= ?0 and c <= ?9, do: digits(text, pos + 1), else: pos
  end

  defp walk_frac(text, pos, integral) do
    if at(text, pos) == ?. do
      after_point = digits(text, pos + 1)
      if after_point == pos + 1, do: :bad, else: walk_exp(text, after_point, false)
    else
      walk_exp(text, pos, integral)
    end
  end

  defp walk_exp(text, pos, integral) do
    c = at(text, pos)

    if c == ?e or c == ?E do
      pos2 = pos + 1
      pos2 = if at(text, pos2) in [?-, ?+], do: pos2 + 1, else: pos2
      after_digits = digits(text, pos2)
      if after_digits == pos2, do: :bad, else: {after_digits, false}
    else
      {pos, integral}
    end
  end

  defp scan_number(text, pos, value, report) do
    start = space(text, pos)

    case walk_number(text, start) do
      :bad ->
        bad(value, report)

      {stop, integral} ->
        size = stop - start
        if size <= 0 or size > @max_number, do: bad(value, report)
        {binary_part(text, start, size), integral, stop}
    end
  end

  # ---- skipping a value the walk will not place ----

  defp skip_value(text, pos, depth, value, report) do
    {c, pos} = peek(text, pos)

    case c do
      ?{ -> skip_container(text, pos + 1, ?}, depth, value, report)
      ?[ -> skip_container(text, pos + 1, ?], depth, value, report)
      ?" -> elem(scan_string(text, pos, 0, value, report), 1)
      ?t -> literal(text, pos, "true", value, report)
      ?f -> literal(text, pos, "false", value, report)
      ?n -> literal(text, pos, "null", value, report)
      0 -> bad(value, report)
      _ -> elem(scan_number(text, pos, value, report), 2)
    end
  end

  defp skip_container(text, pos, close, depth, value, report) do
    if depth > @max_depth, do: bad(value, report)
    {c, pos} = peek(text, pos)

    cond do
      c == close ->
        pos + 1

      c == 0 ->
        bad(value, report)

      true ->
        pos =
          if close == ?} do
            {_key, pos2, _} = scan_string(text, pos, 0, value, report)
            {colon, pos3} = peek(text, pos2)
            if colon != ?:, do: bad(value, report)
            pos3 + 1
          else
            pos
          end

        pos = skip_value(text, pos, depth + 1, value, report)
        {c2, pos2} = peek(text, pos)

        cond do
          # a trailing comma is accepted
          c2 == ?, -> skip_container(text, pos2 + 1, close, depth, value, report)
          c2 == close -> pos2 + 1
          true -> bad(value, report)
        end
    end
  end

  # ---- one table object ----

  defp read_table(value, type, text, pos, depth, report) do
    if depth > @max_depth, do: bad(value, report)
    {c, pos} = peek(text, pos)
    if c != ?{, do: bad(value, report)
    read_entries(value, type, text, pos + 1, depth, report, %{})
  end

  defp read_entries(value, type, text, pos, depth, report, seen) do
    {c, pos} = peek(text, pos)

    cond do
      c == ?} ->
        {value, pos + 1, report}

      c == 0 ->
        bad(value, report)

      true ->
        {key, pos, _} = scan_string(text, pos, @max_key, value, report)
        {colon, pos} = peek(text, pos)
        if colon != ?:, do: bad(value, report)
        pos = pos + 1
        # THE AMPERSAND PREFIX IS RESERVED TO THE FORM (docs/SPEC-TABLES.md
        # 16.7): never a field this build lacks, always a construct it cannot
        # honor. Malformed and refused, never counted as unknown.
        if String.starts_with?(key, "&"), do: bad(value, report)

        {value, pos, report, seen} =
          case Enum.find(type.fields, fn f -> f.json == key end) do
            nil ->
              # a key this reader cannot name
              {value, skip_value(text, pos, depth + 1, value, report), unknown(report), seen}

            f ->
              report = if Map.has_key?(seen, f.key), do: duplicate(report), else: report
              seen = Map.put(seen, f.key, true)
              {value, pos, report} = read_entry(value, f, text, pos, depth, report)
              {value, pos, report, seen}
          end

        {c2, pos2} = peek(text, pos)

        cond do
          c2 == ?, -> read_entries(value, type, text, pos2 + 1, depth, report, seen)
          c2 == ?} -> {value, pos2 + 1, report}
          true -> bad(value, report)
        end
    end
  end

  defp read_entry(value, f, text, pos, depth, report) do
    {shape, pos} = value_shape(text, pos)

    cond do
      shape == :null and f.optional ->
        # null is the absence, not a value: a ?T reads it as ABSENT (§16.2). It
        # is the ONE key that puts a field back at its defaults, so a repeated
        # key whose last occurrence is null cannot leave an earlier value.
        {Map.put(value, f.key, nil), literal(text, pos, "null", value, report), report}

      shape != field_shape(f) ->
        # the wrong JSON type for the kind: skipped, never coerced
        {value, skip_value(text, pos, depth + 1, value, report), kind_mismatch(report)}

      true ->
        read_field(value, f, text, pos, depth, report)
    end
  end

  # the JSON shape a field's declaration takes. A ?T takes T's shape — presence
  # is the KEY's, never the value's — and an enum-keyed array is an OBJECT.
  defp field_shape(f) do
    cond do
      f.array == :string or f.array == :bytes -> :string
      f.array == :keyed -> :object
      f.array != :none -> :array
      f.arms != nil -> :object
      f.table != nil -> :object
      f.enum != nil -> :string
      f.flags != nil -> :array
      f.kind == 1 -> :bool
      true -> :number
    end
  end

  # the same classifier one level down, for an array's elements
  defp element_shape(f) do
    cond do
      f.arms != nil -> :object
      f.table != nil -> :object
      f.enum != nil -> :string
      f.flags != nil -> :array
      f.kind == 1 -> :bool
      true -> :number
    end
  end

  defp read_field(value, f, text, pos, depth, report) do
    case f.array do
      :string ->
        {out, pos, clamped} = scan_string(text, pos, f.bound, value, report)
        report = if clamped, do: clamped(report), else: report
        {Map.put(value, f.key, out), pos, report}

      :bytes ->
        read_base64(value, f, text, pos, report)

      :keyed ->
        read_keyed(value, f, text, pos, depth, report)

      :none ->
        {slot, pos, report} = read_scalar(Map.fetch!(value, f.key), f, text, pos, depth, value, report)
        {Map.put(value, f.key, slot), pos, report}

      _ ->
        read_array(value, f, text, pos, depth, report)
    end
  end

  # a bytes(N) body decoded six bits at a time, exactly as the generated walk
  # does: a body that is not base64 is the wrong SHAPE for the kind, so the
  # field keeps its default and the event is counted
  defp read_base64(value, f, text, pos, report) do
    {c, pos} = peek(text, pos)
    if c != ?", do: bad(value, report)
    decode64(value, f, text, pos + 1, 0, 0, [], 0, false, false, report)
  end

  defp decode64(value, f, text, pos, acc, held, out, used, clamped, malformed, report) do
    cond do
      pos >= byte_size(text) ->
        bad(value, report)

      :binary.at(text, pos) == ?" ->
        cond do
          malformed ->
            {value, pos + 1, kind_mismatch(report)}

          true ->
            report = if clamped, do: clamped(report), else: report
            {Map.put(value, f.key, IO.iodata_to_binary(Enum.reverse(out))), pos + 1, report}
        end

      true ->
        c = :binary.at(text, pos)

        cond do
          c == ?= or malformed ->
            decode64(value, f, text, pos + 1, acc, held, out, used, clamped, malformed, report)

          true ->
            case Enum.find_index(@base64, fn a -> a == c end) do
              nil ->
                decode64(value, f, text, pos + 1, acc, held, out, used, clamped, true, report)

              at ->
                acc2 = (acc <<< 6) ||| at
                held2 = held + 6

                if held2 >= 8 do
                  held3 = held2 - 8
                  byte = acc2 >>> held3 &&& 0xFF

                  if used < f.bound do
                    decode64(value, f, text, pos + 1, acc2, held3, [byte | out], used + 1, clamped, false, report)
                  else
                    decode64(value, f, text, pos + 1, acc2, held3, out, used, true, false, report)
                  end
                else
                  decode64(value, f, text, pos + 1, acc2, held2, out, used, clamped, false, report)
                end
            end
        end
    end
  end

  # an ARRAY re-establishes before placing: a fixed array writes every slot, so
  # a second, shorter occurrence overlaying a prefix would leave the first
  # occurrence's tail standing (§16.2, last-wins as a WHOLE value)
  defp read_array(value, f, text, pos, depth, report) do
    {c, pos} = peek(text, pos)
    if c != ?[, do: bad(value, report)
    {placed, pos, report} = read_elements(value, f, text, pos + 1, depth, report, [], 0)
    list = Enum.reverse(placed)

    filled =
      if f.array == :fixed do
        # a fixed array's tail keeps the declared defaults, exactly as a short
        # wire count does
        list ++ List.duplicate(f.elem_default, f.bound - length(list))
      else
        list
      end

    {Map.put(value, f.key, filled), pos, report}
  end

  defp read_elements(value, f, text, pos, depth, report, acc, placed) do
    {c, pos} = peek(text, pos)

    cond do
      c == ?] ->
        {acc, pos + 1, report}

      c == 0 ->
        bad(value, report)

      true ->
        {acc, pos, report, placed} =
          cond do
            placed >= f.bound ->
              # more elements than the reader's bound: the bounded prefix is
              # kept and the excess counts, the wire's rule (§4)
              {acc, skip_value(text, pos, depth + 1, value, report), clamped(report), placed}

            elem(value_shape(text, pos), 0) != element_shape(f) ->
              {[f.elem_default | acc], skip_value(text, pos, depth + 1, value, report),
               kind_mismatch(report), placed + 1}

            true ->
              {slot, pos2, report2} =
                read_scalar(f.elem_default, f, text, pos, depth + 1, value, report)

              {[slot | acc], pos2, report2, placed + 1}
          end

        {c2, pos2} = peek(text, pos)

        cond do
          c2 == ?, -> read_elements(value, f, text, pos2 + 1, depth, report, acc, placed)
          c2 == ?] -> {acc, pos2 + 1, report}
          true -> bad(value, report)
        end
    end
  end

  # an enum-keyed array is an OBJECT keyed by VARIANT NAME. An absent key keeps
  # that slot's defaults; an unknown key is skipped and counted, and "None" is
  # such a key because None keys no slot (§2.4).
  defp read_keyed(value, f, text, pos, depth, report) do
    {c, pos} = peek(text, pos)
    if c != ?{, do: bad(value, report)
    slots = List.duplicate(f.elem_default, f.bound)
    {slots, pos, report} = read_slots(value, f, text, pos + 1, depth, report, slots, %{})
    {Map.put(value, f.key, if(f.tuple, do: List.to_tuple(slots), else: slots)), pos, report}
  end

  defp read_slots(value, f, text, pos, depth, report, slots, seen) do
    {c, pos} = peek(text, pos)

    cond do
      c == ?} ->
        {slots, pos + 1, report}

      c == 0 ->
        bad(value, report)

      true ->
        {key, pos, _} = scan_string(text, pos, @max_key, value, report)
        {colon, pos} = peek(text, pos)
        if colon != ?:, do: bad(value, report)
        pos = pos + 1
        variant = call1(f.key_enum.value, key)
        index = if variant == nil or variant < 1 or variant > f.bound, do: nil, else: variant - 1

        report =
          if index != nil and Map.has_key?(seen, index), do: duplicate(report), else: report

        seen = if index == nil, do: seen, else: Map.put(seen, index, true)

        {slots, pos, report} =
          cond do
            index == nil ->
              # a key this enum cannot name; "None" is one of them
              {slots, skip_value(text, pos, depth + 1, value, report), unknown(report)}

            elem(value_shape(text, pos), 0) != element_shape(f) ->
              {slots, skip_value(text, pos, depth + 1, value, report), kind_mismatch(report)}

            true ->
              {slot, pos2, report2} =
                read_scalar(Enum.at(slots, index), f, text, pos, depth + 1, value, report)

              {List.replace_at(slots, index, slot), pos2, report2}
          end

        {c2, pos2} = peek(text, pos)

        cond do
          c2 == ?, -> read_slots(value, f, text, pos2 + 1, depth, report, slots, seen)
          c2 == ?} -> {slots, pos2 + 1, report}
          true -> bad(value, report)
        end
    end
  end

  defp read_scalar(slot, f, text, pos, depth, value, report) do
    cond do
      f.arms != nil ->
        read_union(slot, f, text, pos, depth, value, report)

      f.table != nil ->
        type = info(f.table)
        nested = info(type.new)
        {nested, pos, report} = read_table(nested, type, text, pos, depth + 1, report)
        {nested, pos, report}

      f.enum != nil ->
        {name, pos, _} = scan_string(text, pos, @max_key, value, report)

        case call1(f.enum.value, name) do
          nil ->
            # a name this build cannot name reads as None and counts as unknown,
            # exactly as an unknown variant id does on the wire (§4)
            {0, pos, unknown(report)}

          v ->
            {v, pos, report}
        end

      f.flags != nil ->
        read_flags(f, text, pos, depth, value, report)

      f.kind == 1 ->
        {c, pos} = peek(text, pos)

        if c == ?t do
          {true, literal(text, pos, "true", value, report), report}
        else
          {false, literal(text, pos, "false", value, report), report}
        end

      true ->
        {token, integral, pos} = scan_number(text, pos, value, report)

        cond do
          f.kind == 10 -> {place_float(token, f, true, report), pos, nil} |> settle()
          f.kind == 11 -> {place_float(token, f, false, report), pos, nil} |> settle()
          true -> {place_integer(token, integral, f, slot, report), pos, nil} |> settle()
        end
    end
  end

  defp settle({{slot, report}, pos, nil}), do: {slot, pos, report}

  # a magnitude the field's format cannot hold is the WRONG SHAPE for the kind
  # and never reaches storage: storing the infinity the conversion produced
  # would leave an instance this walk called CLEAN that the writer then refuses
  # forever (§16.2, §16.3)
  defp place_float(token, f, single, report) do
    case decimal_to_float(token, single) do
      :infinity ->
        {0.0, kind_mismatch(report)}

      parsed ->
        clamp_range(parsed, f, report)
    end
  end

  # ---- decimal -> binary float, ONE correctly-rounded conversion ----
  #
  # At the field's OWN width, over exact integers. Converting through a double
  # first would round TWICE, and the two roundings part company across a whole
  # band: a decimal between FLT_MAX and the float32 rounding midpoint lands ON
  # the midpoint as a double and overflows from there, and again at the
  # subnormal end, where the double rounds to zero and the single does not.
  # The page's rule is exact conversion at both float widths (§16.2), and the
  # BEAM offers no strtof, so this is it.
  def decimal_to_float(token, single) do
    {precision, min_ulp, overflow_exp} =
      if single, do: {24, -149, 128}, else: {53, -1074, 1024}

    {sign, m, e} = decimal_parts(token)

    if m == 0 do
      0.0 * sign
    else
      {n, d} = if e >= 0, do: {m * pow10(e), 1}, else: {m, pow10(-e)}
      ulp = max(exponent_of(n, d) - (precision - 1), min_ulp)
      {q, ulp} = normalize(round_half_even(n, d, ulp), ulp, precision)

      # q * 2^ulp >= 2^overflow_exp has no float of this width: the value
      # overflows, and no BEAM float term can hold the infinity
      room = overflow_exp - ulp

      if room <= 0 or q >= 1 <<< room do
        :infinity
      else
        sign * q * :math.pow(2.0, ulp)
      end
    end
  end

  defp decimal_parts(token) do
    {sign, rest} =
      case token do
        "-" <> r -> {-1, r}
        "+" <> r -> {1, r}
        r -> {1, r}
      end

    {mantissa, exponent} =
      case String.split(rest, ["e", "E"]) do
        [m] -> {m, "0"}
        [m, x] -> {m, x}
      end

    {whole, fraction} =
      case String.split(mantissa, ".") do
        [i] -> {i, ""}
        [i, f] -> {i, f}
      end

    digits = whole <> fraction
    m = if digits == "", do: 0, else: String.to_integer(digits)
    {sign, m, String.to_integer(exponent) - byte_size(fraction)}
  end

  defp pow10(k), do: Integer.pow(10, k)

  # n/d >= 2^k, over integers
  defp ge_pow2(n, d, k) do
    if k >= 0, do: n >= d <<< k, else: n <<< -k >= d
  end

  # the k with 2^k <= n/d < 2^(k+1)
  defp exponent_of(n, d) do
    k = bit_length(n) - bit_length(d)
    if ge_pow2(n, d, k), do: k, else: k - 1
  end

  defp bit_length(0), do: 0
  defp bit_length(x), do: byte_size(Integer.to_string(x, 2))

  # round(n / (d * 2^ulp)) to nearest, ties to even
  defp round_half_even(n, d, ulp) do
    {num, den} = if ulp >= 0, do: {n, d <<< ulp}, else: {n <<< -ulp, d}
    q = div(num, den)
    r = rem(num, den)
    twice = r * 2

    cond do
      twice > den -> q + 1
      twice < den -> q
      rem(q, 2) == 0 -> q
      true -> q + 1
    end
  end

  # a carry out of the top bit widens the exponent by one
  defp normalize(q, ulp, precision) do
    if q >= 1 <<< precision, do: {div(q, 2), ulp + 1}, else: {q, ulp}
  end

  defp clamp_range(value, f, report) do
    case f.range do
      nil -> {value, report}
      {lo, hi} -> clamp(value, lo, hi, report)
    end
  end

  # JSON HAS ONE NUMBER TYPE, so an integer field takes any token whose VALUE is
  # integral, however it was spelled — 2, 2.0 and 1e3 are all the integers this
  # walk places — and only a genuinely fractional value is the wrong shape for
  # it (§16.2)
  defp place_integer(token, integral, f, slot, report) do
    {value, saturated, ok} =
      if integral do
        token_integer(token, f)
      else
        case Float.parse(token) do
          {d, ""} ->
            if d == Float.round(d) and abs(d) < 1.0e18 do
              {trunc(d), false, true}
            else
              if abs(d) >= 1.0e18, do: {saturate(d, f), true, true}, else: {0, false, false}
            end

          _ ->
            {0, false, false}
        end
      end

    cond do
      not ok ->
        {slot, kind_mismatch(report)}

      true ->
        report = if saturated, do: clamped(report), else: report
        {value, report} = clamp_range(value, f, report)
        clamp_storage(value, f, report)
    end
  end

  defp saturate(d, f) do
    signed = f.kind >= 2 and f.kind <= 5

    cond do
      not signed and d < 0.0 -> 0
      not signed -> 0xFFFFFFFFFFFFFFFF
      d < 0.0 -> -0x8000000000000000
      true -> 0x7FFFFFFFFFFFFFFF
    end
  end

  # converted digit by digit so no width and no locale can move it; saturation
  # is reported as a clamp, the wire's rule for a value outside what the reader
  # can hold (§4)
  defp token_integer(token, f) do
    signed = f.kind >= 2 and f.kind <= 5
    {negative, digits} =
      case token do
        "-" <> rest -> {true, rest}
        "+" <> rest -> {false, rest}
        rest -> {false, rest}
      end

    magnitude = String.to_integer(digits)

    cond do
      not signed and negative -> {0, magnitude != 0, true}
      not signed and magnitude > 0xFFFFFFFFFFFFFFFF -> {0xFFFFFFFFFFFFFFFF, true, true}
      not signed -> {magnitude, false, true}
      negative and magnitude > 0x8000000000000000 -> {-0x8000000000000000, true, true}
      negative -> {-magnitude, false, true}
      magnitude > 0x7FFFFFFFFFFFFFFF -> {0x7FFFFFFFFFFFFFFF, true, true}
      true -> {magnitude, false, true}
    end
  end

  # the field's own storage width is the last bound: a value past it clamps
  # rather than wrapping, which is what the wire does too
  defp clamp_storage(value, f, report) do
    bytes = f.storage_bytes

    if bytes <= 0 or bytes >= 8 do
      {value, report}
    else
      signed = f.kind >= 2 and f.kind <= 5

      if signed do
        hi = (1 <<< (bytes * 8 - 1)) - 1
        clamp(value, -hi - 1, hi, report)
      else
        clamp(value, 0, (1 <<< (bytes * 8)) - 1, report)
      end
    end
  end

  defp read_union(slot, f, text, pos, depth, value, report) do
    # a union is an object with ONE key, the arm's name; {} is None, and two
    # keys is a text this walk will not guess at
    {c, pos} = peek(text, pos)
    if c != ?{, do: bad(value, report)
    arms = info(f.arms)
    empty = info(f.union_new)
    {c2, pos} = peek(text, pos + 1)

    if c2 == ?} do
      {empty, pos + 1, report}
    else
      {key, pos, _} = scan_string(text, pos, @max_key, value, report)
      {colon, pos} = peek(text, pos)
      if colon != ?:, do: bad(value, report)
      pos = pos + 1

      tag =
        arms
        |> Enum.with_index()
        |> Enum.find_value(fn {arm, i} -> if i > 0 and arm.name == key, do: i, else: nil end)

      {slot, pos, report} =
        if tag == nil do
          {slot, skip_value(text, pos, depth + 1, value, report), unknown(report)}
        else
          arm = Enum.at(arms, tag)
          type = info(arm.table)
          payload = info(type.new)
          {payload, pos2, report2} = read_table(payload, type, text, pos, depth + 1, report)
          {Map.put(Map.put(empty, :type, tag), arm.key, payload), pos2, report2}
        end

      {c3, pos} = peek(text, pos)
      pos = if c3 == ?,, do: pos + 1, else: pos
      {c4, pos} = peek(text, pos)
      # a second key: a one-of with two arms is not a value
      if c4 != ?}, do: bad(value, report)
      {slot, pos + 1, report}
    end
  end

  defp read_flags(f, text, pos, depth, value, report) do
    {c, pos} = peek(text, pos)
    if c != ?[, do: bad(value, report)
    read_flag_names(f, text, pos + 1, depth, value, report, 0)
  end

  defp read_flag_names(f, text, pos, depth, value, report, bits) do
    {c, pos} = peek(text, pos)

    cond do
      c == ?] ->
        {bits, pos + 1, report}

      c == 0 ->
        bad(value, report)

      true ->
        {bits, pos, report} =
          if c != ?" do
            {bits, skip_value(text, pos, depth + 1, value, report), kind_mismatch(report)}
          else
            {name, pos2, _} = scan_string(text, pos, @max_key, value, report)

            case Enum.find_index(f.flags, fn v -> v == name end) do
              nil -> {bits, pos2, unknown(report)}
              bit -> {bits ||| 1 <<< bit, pos2, report}
            end
          end

        {c2, pos2} = peek(text, pos)

        cond do
          c2 == ?, -> read_flag_names(f, text, pos2 + 1, depth, value, report, bits)
          c2 == ?] -> {bits, pos2 + 1, report}
          true -> bad(value, report)
        end
    end
  end
end
